INSERT INTO user_session(
    id, user_id, token_digest, credential_version, expires_at, last_used_at, created_at
) VALUES (#{p.id}, #{p.userId}, #{p.tokenDigest}, #{p.credentialVersion}, #{p.expiresAt}, #{p.now}, #{p.now})


UPDATE user_session
SET revoked_at = #{p.now}, revoked_reason = #{p.reason}
WHERE id = #{p.sessionId} AND revoked_at IS NULL


UPDATE user_session
SET revoked_at = #{p.now}, revoked_reason = #{p.reason}
WHERE user_id = #{p.userId} AND revoked_at IS NULL

