SELECT EXISTS (
    SELECT 1
    FROM auth_rate_limit
    WHERE entry_point = 'LOGIN' AND subject_digest = #{p.subjectDigest}
      AND locked_until > #{p.now}
)


SELECT failure_count, locked_until
FROM auth_rate_limit
WHERE entry_point = 'LOGIN' AND subject_digest = #{p.subjectDigest}
  AND window_started_at = #{p.windowStart}
FOR UPDATE

