UPDATE auth_rate_limit
SET failure_count = #{p.failures}, locked_until = #{p.lockedUntil}, updated_at = #{p.now}
WHERE entry_point = 'LOGIN' AND subject_digest = #{p.subjectDigest}
  AND window_started_at = #{p.windowStart}
